// Monitor other scripts in the object, then report, restart or both if some have crashed
// NB: cannot distinguish a manually stopped script or restart one
integer
TRY_RESTART
=
FALSE
;
integer
REPORT
=
TRUE
;
default
{
state_entry
()
{
// monitoring rate = once per minute
llSetTimerEvent
(
60
);
}
timer
()
{
integer
i
=
llGetInventoryNumber
(
INVENTORY_SCRIPT
);
string
script_name
;
list
stopped
;
while
(
--
i
>=
0
)
{
// the script will also monitor itself, but there is little reason to specifically skip
script_name
=
llGetInventoryName
(
INVENTORY_SCRIPT
,
i
);
if
(
!
llGetScriptState
(
script_name
))
{
if
(
TRY_RESTART
)
llResetOtherScript
(
script_name
);
if
(
REPORT
)
stopped
+=
script_name
;
}
}
if
(
stopped
)
{
string
message
=
"The following scripts were crashed/stopped: "
+
llList2CSV
(
stopped
)
+
"."
;
if
(
TRY_RESTART
)
message
+=
" A restart was attempted."
;
llInstantMessage
(
llGetOwner
(),
message
);
}
}
}
